export function Hamster({
  mood = "sparkle",
  size = 240,
  coin = true,
  sparkles = false,
  animated = false,
  className,
  title = "Hamstr Maskottchen",
}: HamsterProps) {
  const p = "h" + useId().replace(/[^a-zA-Z0-9]/g, "");
  const hands = coin ? (animated ? COIN_ANIMATED : COIN_STATIC) : NO_COIN;
  const body = (animated ? BODY_ANIMATED : BODY_STATIC)
    .replace("__EYES__", EYES[mood])
    .replace("__SPARKLES__", sparkles ? SPARKLES : "")
    .replace("__HANDS__", hands);
  const html = (`<defs>${DEFS}</defs>` + (animated ? `<style>${CSS}</style>` : "") + body).replaceAll("__P__", p);
  return (
    <svg
      viewBox="0 0 512 512"
      width={size}
      height={size}
      className={className}
      role={title ? "img" : undefined}
      aria-label={title || undefined}
      aria-hidden={title ? undefined : true}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}

