/**
 * Turns the rig around in pseudo-3D: every feature sits on a sphere and slides/foreshortens as the
 * body rotates, the ears swap sides, the coin and snout stick out in profile. Faces away, wiggles
 * its bum (tail wag, bun jiggle, hearts) and completes the 360° turn. Returns a stop function.
 */
function turnHamster(svg: SVGSVGElement, p: string, done?: () => void): () => void {
  const R = 195, CX = 256, T = 2600, PI = Math.PI;
  const q = (c: string) => svg.querySelector<SVGGElement>(`.${p}-${c}`);
  const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));
  const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
  const parts = Array.from(svg.querySelectorAll<SVGGElement>("[data-x]")).map((el) => {
    const x0 = Number(el.getAttribute("data-x"));
    const r = Number(el.getAttribute("data-r") || R);
    const a = Math.asin(clamp(x0 / r, -0.999, 0.999));
    return {
      el, x0, r,
      phi0: el.getAttribute("data-s") === "b" ? a + PI : a,
      rest: Math.cos(a),
      m: Number(el.getAttribute("data-m") || 0.04),
      k: el.getAttribute("data-k"),
      inner: el.querySelector<SVGElement>(`.${p}-earin`),
    };
  });
  const root = q("root"), bodyg = q("bodyg"), tail = q("tail"), bunL = q("bunL"), bunR = q("bunR");
  const theta = (t: number) =>
    t < 120 ? 0 : t < 620 ? PI * ease((t - 120) / 500) : t < 1800 ? PI : t < 2300 ? PI + PI * ease((t - 1800) / 500) : 2 * PI;

  const pose = (th: number, t: number) => {
    for (const o of parts) {
      const phi = o.phi0 - th, c = Math.cos(phi), x = o.r * Math.sin(phi);
      let sc: number, vis: number;
      if (o.k === "feetf" || o.k === "feetb") {
        const cf = Math.cos(th) * (o.k === "feetb" ? -1 : 1);
        o.el.setAttribute("opacity", String(clamp((cf + 0.25) / 0.5, 0, 1)));
        continue;
      }
      if (o.k === "ear") {
        sc = 0.72 + 0.28 * Math.abs(c); vis = 1;
        o.inner?.setAttribute("opacity", String(clamp(c * 2.5, 0, 1)));
      } else {
        sc = Math.max(c, o.m) / Math.max(o.rest, o.m);
        vis = o.k === "late" ? clamp((c - 0.3) / 0.3, 0, 1) : clamp((c + 0.02) / 0.3, 0, 1);
      }
      o.el.setAttribute("opacity", String(vis));
      o.el.setAttribute("transform", `translate(${CX + x} 0) scale(${sc} 1) translate(${-(CX + o.x0)} 0)`);
    }
    const sw = 1 - 0.09 * Math.pow(Math.sin(th), 2);
    bodyg?.setAttribute("transform", `translate(256 0) scale(${sw} 1) translate(-256 0)`);
    let dy = 0, sx = 1, sy = 1, wig = 0, tw = 0, jl = 1, jr = 1;
    const hop = (a: number, b: number, h: number) => { if (t > a && t < b) dy -= Math.sin((PI * (t - a)) / (b - a)) * h; };
    const squash = (a: number, b: number) => {
      if (t > a && t < b) { const u = Math.sin((PI * (t - a)) / (b - a)); sx += 0.07 * u; sy -= 0.09 * u; }
    };
    hop(120, 620, 56); hop(1800, 2300, 50);
    squash(0, 140); squash(600, 760); squash(2280, 2460);
    if (t > 760 && t < 1760) {
      const u = (t - 760) / 1000, env = Math.sin(PI * u);
      wig = 9 * Math.sin(2 * PI * 3 * u) * env;
      tw = 28 * Math.sin(2 * PI * 8 * u) * env;
      jl = 1 + 0.07 * Math.sin(2 * PI * 3 * u + PI / 2) * env;
      jr = 1 + 0.07 * Math.sin(2 * PI * 3 * u - PI / 2) * env;
    }
    root?.setAttribute("transform", `translate(0 ${dy}) rotate(${wig} 256 470) translate(256 480) scale(${sx} ${sy}) translate(-256 -480)`);
    if (tail) tail.style.transform = `rotate(${tw}deg)`;
    if (bunL) bunL.style.transform = `scale(${(2 - jl) * 0.5 + 0.5},${jl})`;
    if (bunR) bunR.style.transform = `scale(${(2 - jr) * 0.5 + 0.5},${jr})`;
  };

  const cls = [`${p}-playing`, `${p}-happy`];
  const finish = () => { pose(0, T); svg.classList.remove(...cls); };
  svg.classList.remove(...cls);
  void svg.getBoundingClientRect();
  svg.classList.add(...cls);
  if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
    const id = setTimeout(() => { finish(); done?.(); }, 1200);
    return () => { clearTimeout(id); finish(); };
  }
  let start: number | null = null, raf = 0;
  const frame = (now: number) => {
    if (start === null) start = now;
    const t = now - start;
    if (t >= T) { finish(); done?.(); return; }
    pose(theta(t), t);
    raf = requestAnimationFrame(frame);
  };
  pose(0, 0);
  raf = requestAnimationFrame(frame);
  return () => { cancelAnimationFrame(raf); finish(); };
}

/**
 * Clickable mascot easter egg. On click the hamster hops, turns around in 3D, wiggles its big fluffy
 * bum (tail wag, bun jiggle, floating hearts) and completes the turn with a happy face.
 * It is a real <button> (keyboard + screen reader); prefers-reduced-motion gets hearts only.
 * Same props as <Hamster /> (except `coin`, always on) plus `label`, the button's accessible name.
 */
export function HamsterPet({
  label = "Pet the hamster",
  size = 240,
  mood = "sparkle",
  sparkles = false,
  animated = false,
  className,
}: Omit<HamsterProps, "coin" | "title"> & { label?: string }) {
  const p = "q" + useId().replace(/[^a-zA-Z0-9]/g, "");
  const ref = useRef<SVGSVGElement>(null);
  const stop = useRef<(() => void) | undefined>(undefined);
  useEffect(() => () => stop.current?.(), []);
  const html = RIG.replace("__EOL__", RIG_EYES[mood][0])
    .replace("__EOR__", RIG_EYES[mood][1])
    .replace("__SPARKLES__", sparkles ? RIG_SPARKLES : "")
    .replace("__ANIM__", animated ? CSS : "")
    .replaceAll("__P__", p);
  return (
    <button
      type="button"
      aria-label={label}
      onClick={() => {
        if (!ref.current) return;
        stop.current?.();
        stop.current = turnHamster(ref.current, p, () => (stop.current = undefined));
      }}
      style={{ appearance: "none", background: "none", border: 0, padding: 0, cursor: "pointer", lineHeight: 0, borderRadius: "50%" }}
      className={className}
    >
      <svg ref={ref} viewBox="0 0 512 512" width={size} height={size} aria-hidden overflow="visible" dangerouslySetInnerHTML={{ __html: html }} />
    </button>
  );
}
